head.script:
scwin.onpageload = function () {

};

scwin.new_task_onclick = function (e) {
    //팝업 호출
    //팝업 화면에 데이터를 전달 (dataObject를 통해 전달 가능)
    // var jsnPopupData = {
    //     "type": "json", // 데이터 유형. "json"을 권장
    //     "name": "exam_param",  // 데이터를 가져오기 위한 파라미터 이름으로 팝업 화면에서 $p.getParameter("exam_param")로 추출할 수 있음
    //     "data": {
    //         "Personal_Info": { "Name": "Lee", "Age": 50, "Married": false },
    //         "Region": "Seoul"
    //     } // 실제 전달할 데이터
    // };

    // 팝업 생성 옵션 지정
    var options = {
        id: "exa_popup",
        type: "wframePopup",
        width: "600",
        height: "400",
        top: "100",
        left: "200px",
        popupName: "TASK",
        modal: false,
        closeAction: "scwin.popup_closeAction", 
        customTitleBar: false
    };

    // 팝업 생성
    $p.openPopup("./testModal.xml", options);

};
// 팝업 생성 옵션의 closeAction 함수 정의 예시
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    var popObj = $p.getPopupWindow(argRuntimeID);
    return true; //팝업 닫기 (반환 값이 true인 경우만 팝업이 닫힘)
};
